import { defineTexture } from '../engine/defs.js';

// Wall, floor, ceiling and sky textures. Walls/flats are 64x64 PNGs in
// assets/textures/ (animated ones are horizontal strips of 64x64 frames;
// jambs are 16x64 and 32x64 and the gate 128x128, the size of what they cover),
// generated by tools/art/textures/imperial.js. Fence textures (railings, bars,
// grates) have transparent pixels and keep their own sizes.
// To add a texture: drop a PNG in assets/textures/ and add its name here.

const STATIC = [
  // Imperial walls
  'imp-panel', 'imp-panel-dark', 'imp-lights', 'imp-vent', 'imp-stripe',
  // Floors and ceilings
  'imp-floor', 'imp-grate', 'imp-ceiling', 'imp-ceiling-light', 'lift-floor',
  // Doors and switches
  'imp-door', 'imp-door-red', 'imp-door-blue', 'imp-door-yellow', 'imp-gate', 'imp-gate-jamb', 'imp-jamb', 'imp-lintel', 'imp-switch', 'imp-switch-on',
  // The canyon outside
  'canyon-rock', 'sand',
];

// Tatooine's sandstone strata, sand and gravel (tools/art/textures/desert.js).
// Rock never glows: its colours snap to lit ones only.
const DESERT = ['sandstone', 'sandstone-dark', 'sandstone-pale', 'desert-sand', 'desert-gravel'];

// See-through fences (railings, bars, grates): any size, with holes.
const FENCES = ['imp-railing', 'imp-bars', 'imp-cage'];

// Decals on wall faces (tools/art/textures/decals.js): signs, the crest,
// hazard stripes and a vent.
const DECALS = ['decal-crest', 'decal-hazard', 'decal-sign', 'decal-vent'];

// Mos Eisley (Mark, 2026-10-17: Dark Forces textures for now, no generated
// stand-ins): DF textures recoloured by assets/custom/derive.mjs, loaded from
// there directly.
const TOWN = ['adobe', 'adobe-pale', 'adobe-old', 'adobe-brick', 'adobe-roof', 'planks', 'street-sand', 'flagstone'];

const ANIMATED = {
  'imp-computer': { frames: 3, fps: 3 },
};

export default [
  ...STATIC.map((id) => defineTexture({ id, src: `assets/textures/${id}.png` })),
  ...DESERT.map((id) => defineTexture({ id, src: `assets/textures/${id}.png`, fullbright: false })),
  ...Object.entries(ANIMATED).map(([id, a]) => defineTexture({ id, src: `assets/textures/${id}.png`, ...a })),
  ...FENCES.map((id) => defineTexture({ id, src: `assets/textures/${id}.png`, fence: true })),
  ...DECALS.map((id) => defineTexture({ id, src: `assets/textures/${id}.png`, decal: true })),
  ...TOWN.map((id) => defineTexture({ id, src: `assets/custom/textures/${id}.png`, fullbright: false })),
  defineTexture({ id: 'sky-night', src: 'assets/textures/sky-night.png', sky: true }),
  defineTexture({ id: 'sky-day', src: 'assets/custom/textures/sky-day.png', sky: true }),
];
